/* Add useful editorial context to the preserved original homepage. */
(function () {
  'use strict';
  if (location.pathname !== '/') return;
  var tries = 0, timer;
  function mount() {
    var host = document.getElementById('sr-seaside-root');
    var home = host && host.shadowRoot && host.shadowRoot.querySelector('#sr-home-approved-20260921');
    var root = home && home.shadowRoot;
    if (!root || !host.querySelector('#sr-home-native-guide')) return false;
    if (root.querySelector('#sr-home-purpose')) return true;
    var main = root.querySelector('main');
    var monthly = Array.from(main.children).find(function (s) { var h=s.querySelector('h2'); return h && /highlights/i.test(h.textContent); });
    var destinations = Array.from(main.children).find(function (s) { var h=s.querySelector('h2'); return h && /Explore by\s+destination/i.test(h.textContent); });
    if (!monthly || !destinations) return false;
    var intro = document.createElement('section');
    intro.id='sr-home-purpose'; intro.className='section wrap sr-home-added';
    intro.innerHTML='<div class="heading"><h2>There’s a whole <em>day out in here.</em></h2></div><div class="sr-added-intro"><p>That first glimpse of the sea. The kids spotting a roller coaster before you’ve even parked. Fish and chips on the prom, candy floss on your fingers and a game on the pier that suddenly has the whole family involved. Those are the bits you remember. Spin Raiders is here to help you find more of them, right across the UK.</p><p>Bring the seaside nostalgia, the wildlife adventures, the fishing trips and the big attractions together with somewhere good to eat and a bed for the night. You can start with a town, follow something you love or read about one of our own visits. Then use the Trip Builder to bring your choices into one plan, instead of losing them across a dozen open tabs.</p><p>I’m Jamie. When I’ve been, you’ll get my own photographs, what made the visit and the bits I had a moan about too. Our wider guides help you discover places beyond those personal visits. You’ll find the monthly picks, full reviews and offers here together, so you can decide what deserves a place in <strong>your</strong> day.</p></div>';
    monthly.before(intro);
    var experiences=document.createElement('section');
    experiences.id='sr-home-day-stories'; experiences.className='section wrap sr-home-added';
    experiences.innerHTML='<div class="heading"><h2>What sort of day <em>are we having?</em></h2></div><div class="sr-added-stories"><article><h3>The seaside, with all the trimmings</h3><p>Bring your own childhood favourites back to life: the pier, the beach, the silly souvenir and the argument over who gets the last chip. Or give the kids their first go. Start with our seaside towns, then look at the piers, attractions and food around them. A beach afternoon and a big-ticket attraction make very different days; choose the bit everyone is looking forward to first.</p><a href="/seaside">Find your seaside day →</a></article><article><h3>Wildlife that makes everyone stop talking</h3><p>A giraffe appearing above the fence or a shark passing overhead can put the phones away quicker than any parent. Compare zoos and wildlife parks with aquariums: do you fancy a day outdoors following the animals, or an underwater world under a roof? Follow the individual guide for the animals, visitor information and location that help you choose.</p><a href="/zoos">Zoos &amp; wildlife →</a> <a href="/sea-life">Aquariums →</a></article><article><h3>A rod, a lake and a proper change of pace</h3><p>Some days need fewer queues and more time by the water. Our fishing pages give you a place to start, whether you’re looking for a fishery for the day or somewhere to turn it into a break. Compare the type of fishing and the facilities you need; then follow the fishery’s own information for its tickets, tackle rules and booking arrangements.</p><a href="/fishing-lakes">Find a fishing trip →</a></article><article><h3>Big screams, small discoveries</h3><p>Is this a roller-coaster day, a castle to investigate or a museum where one exhibit sends you off down a completely unexpected rabbit hole? There’s room for all of them here. Use the attraction guides to find your main event, then the destination page to see what’s around it. The point is to enjoy the place you chose, with another good discovery nearby if you fancy it.</p><a href="/theme-parks">Theme parks →</a> <a href="/museums">Museums →</a> <a href="/historical-sites">Historic places →</a></article><article><h3>Food worth talking about on the way home</h3><p>Our Pizza Parlour order has a kebab calzone at the centre of it. At Masala n Malt, it’s the curries, freshly cooked Peshwari naan and the welcome from Sid and Riju. That’s the sort of detail you’ll get from our own meals. Read the reviews below, then use the food guides to find something that makes lunch or dinner part of the outing.</p><a href="/food-and-drink">Find something good to eat →</a></article><article><h3>Make a night of it</h3><p>When nobody wants to head home just yet, have a look at the stays and holiday parks alongside your day-out ideas. Pick your attraction or destination first, then compare where you’d actually like to spend the evening. Keep the places you fancy together in the planner and add your own accommodation quote to see what the break could cost.</p><a href="/places-to-stay">Places to stay →</a> <a href="/holiday-parks">Holiday parks →</a></article></div>';
    destinations.after(experiences);
    var planner=document.createElement('section');
    planner.id='sr-home-trip-builder'; planner.className='section wrap sr-home-added';
    planner.innerHTML='<div class="sr-added-planner"><span class="sr-added-kicker">YOUR IDEAS, ONE PLAN</span><h2>Right, let’s <em>put a day together.</em></h2><p>Fancy the wildlife park, lunch afterwards and somewhere to stay? Or a museum, a cinema and a meal with the family? The Trip Builder is where those separate ideas become your own outing.</p><ol><li><strong>Pick your places.</strong> Search for towns, attractions, food, fishing and stays inside the builder, then add the ones you fancy.</li><li><strong>Make it your day.</strong> Arrange your stops across the days you have. Add your group size and the prices you’ve found to build a budget.</li><li><strong>Keep it handy.</strong> Save the plan on this browser, or use the builder’s print and export options to take it with you.</li></ol><p class="sr-added-small">Your plan is yours to arrange. Adding a stop doesn’t book tickets or accommodation.</p><a class="button yellow" href="/plan-a-trip">Open the Trip Builder →</a><a class="sr-added-nearby" href="/map">Still choosing? See places on the map →</a></div>';
    experiences.after(planner);
    var style=document.createElement('style');
    style.textContent='.sr-home-added{box-sizing:border-box;padding-top:36px;padding-bottom:36px}.sr-home-added h2{color:#0b3150;font-size:clamp(30px,3vw,44px);line-height:1.12;margin:0 0 20px}.sr-home-added h2 em{color:#0879d9}.sr-home-added p{font-size:18px;line-height:1.7;color:#163c56;margin:0 0 18px}.sr-added-intro{max-width:1050px}.sr-added-stories{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:30px 48px}.sr-added-stories article{border-top:5px solid #ffd927;padding-top:17px}.sr-added-stories article:nth-child(3n+2){border-color:#ff0081}.sr-added-stories article:nth-child(3n){border-color:#00bed3}.sr-added-stories h3{font-size:26px;line-height:1.2;color:#0b3150;margin:0 0 12px}.sr-home-added a:not(.button){font-weight:700;color:#0066b5;display:inline-block;margin:0 16px 8px 0}.sr-added-planner{padding:32px;border-radius:16px;background:linear-gradient(110deg,#e6f9ff,#f4fcff);border:2px solid #b8e8ef;box-shadow:0 6px 0 #00bfd1}.sr-added-kicker{font-weight:800;letter-spacing:.08em;color:#0b5471}.sr-added-planner ol{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;padding-left:24px;font-size:17px;line-height:1.6;color:#163c56}.sr-added-planner li strong{display:block;color:#0b3150}.sr-added-planner .sr-added-small{font-size:14px}.sr-added-planner .button{margin:0 20px 12px 0}.sr-added-nearby{font-size:16px}@media(max-width:650px){.sr-home-added{padding-top:26px;padding-bottom:26px}.sr-home-added p{font-size:17px;line-height:1.6}.sr-added-stories{grid-template-columns:1fr;gap:25px}.sr-added-planner{padding:22px 18px}.sr-added-planner ol{grid-template-columns:1fr;gap:14px}.sr-added-planner .button{max-width:100%;white-space:normal}}';
    style.textContent += '.sr-home-added a:not(.button){font-size:17px;line-height:1.5}.sr-added-kicker{font-size:14px;line-height:1.5}';
    root.appendChild(style);
    return true;
  }
  if (!mount()) timer=setInterval(function(){if(mount()||++tries>150)clearInterval(timer)},100);
})();
